actions.script:
const L = (text) => ec.l10n.localize(text)
newCode = ec.web.sessionAttributes.remove('newEdgePairingCode') || null
newCodeExpire = ec.web.sessionAttributes.remove('newEdgePairingExpire') || ''
const link = ec.service.sync().name('org.moqui.edge.EdgeServices.get#LinkStatus').call() || {}
notBuilt = link.state === 'notBuilt'
notStarted = link.state === 'notStarted'
// a dedicated edge node and an all-in-one node both take links (plans/Edge-Node.md §10)
notEdge = !notBuilt && !notStarted && !['edge', 'all-in-one'].includes(link.nodeRole)
isEdge = !notBuilt && !notStarted && !notEdge
allInOne = isEdge && link.nodeRole === 'all-in-one'
conflictList = []
clientList = []
cursorList = []
clientsError = ''
hostList = []
nodeOptions = []
// empty when the HTTPS listener is off: the link key is loaded with it
linkKey = {linkFingerprint: isEdge ? link.linkFingerprint || '' : ''}
if (!isEdge) return
// a probe (Practices-App-Dev §4): an edge node whose HTTPS listener is off takes no links, and the page says so
let out = {}
let hostsOut = {}
let queueOut = {}
let conflictsOut = {}
ec.message.pushErrors()
try {
    out = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeClients').call() || {}
    if (!ec.message.hasError()) hostsOut = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeHosts').call() || {}
    if (!ec.message.hasError()) {
        queueOut = ec.service.sync().name('org.moqui.edge.EdgeServices.get#QueueStatus').call() || {}
    }
    if (!ec.message.hasError() && allInOne) {
        conflictsOut = ec.service.sync().name('org.moqui.edge.EdgeServices.get#ReplicaConflicts').call() || {}
    }
    if (ec.message.hasError()) clientsError = ec.message.getErrorsString()
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (clientsError) return
// each node's queue: the items waiting for it (all kinds) and the failed ones, and the oldest waiting
const queues = {}
for (const kind of Array.from(queueOut.kindList || [])) {
    if (kind.directionEnumId !== 'EqdToLocal') continue
    const queue = queues[kind.pairedNodeId] ||
        (queues[kind.pairedNodeId] = {pending: 0, failed: 0, oldest: null})
    queue.pending += Number(kind.pending || 0)
    queue.failed += Number(kind.failed || 0)
    if (kind.oldestAgeSeconds != null) queue.oldest = Math.max(queue.oldest ?? 0, Number(kind.oldestAgeSeconds))
}
const age = (seconds) => seconds == null ? '' : seconds < 120 ? seconds + ' s' : seconds < 7200
    ? Math.round(seconds / 60) + ' min' : Math.round(seconds / 3600) + ' h'
cursorList = Array.from(queueOut.cursorList || []).map((cursor) => ({
    nodeId: cursor.pairedNodeId, setName: cursor.setName,
    epochText: cursor.epoch ? String(cursor.epoch).slice(0, 8) : '', seqText: String(cursor.sequenceNum ?? 0),
    valuesText: String(cursor.values ?? 0),
    appliedText: cursor.appliedDate ? ec.l10n.format(cursor.appliedDate, '') : '',
    snapshotText: cursor.snapshotDate ? ec.l10n.format(cursor.snapshotDate, '') : L('Not yet')}))
clientList = Array.from(out.clientList || []).map((client) => {
    const revoked = client.statusId === 'EdgeClientRevoked'
    const [stateLabel, stateColor] = revoked ? [L('Revoked'), 'negative']
        : client.linked && client.down ? [L('Linked'), 'positive']
        : client.linked ? [L('Connecting'), 'info'] : [L('Offline'), 'grey']
    return {pairedNodeId: client.pairedNodeId, stateLabel, stateColor, revoked, linked: !!client.linked && !!client.down,
        generationText: client.generation ? String(client.generation) : '',
        lastConnectText: client.lastConnectDate ? ec.l10n.format(client.lastConnectDate, '') : L('Never'),
        remoteAddress: client.remoteAddress || '',
        versionText: (client.binaryVersion || '') + (client.linkVersion ? ' · ' + L('link') + ' ' + client.linkVersion : ''),
        keyFingerprint: client.keyFingerprint || '',
        keyShort: client.keyFingerprint ? String(client.keyFingerprint).slice(0, 16) + '…' : '',
        setupText: (() => {
            const setup = client.setup
            if (!setup) return L('Not yet')
            const parts = []
            if ((setup.mailDomains || []).length) parts.push(L('mail') + ' ' + Array.from(setup.mailDomains).join(', '))
            if ((setup.chatBridgeIds || []).length) parts.push(ec.resource.expand('${n} chat bridges', '', {n: setup.chatBridgeIds.length}))
            if ((setup.passSites || []).length) parts.push(L('PASS') + ' ' + Array.from(setup.passSites).join(', '))
            const when = client.setupDate ? ' (' + ec.l10n.format(client.setupDate, '') + ')' : ''
            return (parts.length ? parts.join('; ') : L('Host names only')) + when
        })(),
        queueText: (() => {
            const queue = queues[client.pairedNodeId]
            if (!queue) return L('Empty')
            let text = queue.pending + ' ' + L('waiting')
            if (queue.oldest != null) text += ' (' + L('oldest') + ' ' + age(queue.oldest) + ')'
            if (queue.failed) text += ', ' + queue.failed + ' ' + L('failed')
            return text
        })()}
})
conflictList = Array.from(conflictsOut.conflictList || []).map((conflict) => ({
    nodeId: conflict.pairedNodeId, setName: conflict.setName,
    itemText: (conflict.claimLabel || '') + ' ' + (conflict.itemKey || ''),
    ownerText: conflict.ownerText || '',
    lastText: conflict.lastDate ? ec.l10n.format(conflict.lastDate, '') : ''}))
nodeOptions = clientList.filter((client) => !client.revoked).map((client) => ({nodeId: client.pairedNodeId}))
hostList = Array.from(hostsOut.hostList || []).map((host) => {
    const terminate = host.modeEnumId === 'EdgeHostTerminate'
    return {hostName: host.hostName, nodeId: host.pairedNodeId,
        modeLabel: terminate ? L('Terminate') : L('Passthrough'), modeColor: terminate ? 'warning' : 'positive'}
})
